from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[4];BASE=ROOT/"experiments/yolo/gdt381_relational_topology_transfer";ART=BASE/"artifacts"
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def content(o):q=dict(o);q.pop("content_hash",None);return hashlib.sha256(json.dumps(q,sort_keys=True,separators=(",",":")).encode()).hexdigest()
def load(name,path):s=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(s);sys.modules[name]=m;s.loader.exec_module(m);return m
def main():
 target=load("gdt381_target_overlap",BASE/"src/run_target.py");runner=load("gdt381_runner_overlap",BASE/"src/run_comparator.py");freeze=json.loads((ART/"gdt381_voynich_target_freeze.json").read_text());primary=json.loads((ART/"gdt381_voynich_result.json").read_text());assert primary["promotion"] and not primary["formal_realizations_inspected"]
 raw,obs,_=target.read_source();domains=np.array([r["domain"] for r in obs]);indices={d:np.where(domains==d)[0].tolist() for d in sorted(set(domains))};design=json.loads((ART/"gdt381_comparator_topology_freeze.json").read_text());_,_,n,t,rel,nn,tn,rn,*_=runner.build_topology(obs,indices,design);X=np.column_stack([n,t,rel]);names=nn+tn+rn;mu=np.array(freeze["comparator_model"]["training_mean"]);sd=np.array(freeze["comparator_model"]["training_sd"]);beta=np.array(freeze["comparator_model"]["coefficients"]);Z=X.copy();Z[:,1:]=(Z[:,1:]-mu)/sd;full_logit=Z@beta;score=target.sigmoid(full_logit);membership=np.zeros(len(raw),int)
 for register in sorted(set(r["register"] for r in raw)):
  ids=np.array([i for i,r in enumerate(raw) if r["register"]==register]);membership[ids]=(score[ids]>=np.quantile(score[ids],freeze["comparator_model"]["selected_within_domain_quantile"])).astype(int)
 source_names={"INTERCEPT","LOG_RECORD_LENGTH","RELATIVE_POSITION","RELATIVE_POSITION_SQ","BOUNDARY_BEFORE","BOUNDARY_AFTER","LOG_WITHIN_RECORD_RECURRENCE","IS_RECORD_START","IS_RECORD_END","PREV_CLASS_CHANGE","LOG_CURRENT_CLASS_SIZE","CURRENT_CLASS_SIZE_RANK","LOG_PREV_OUTDEGREE","LOG_PREV_CURRENT_EDGE"};source_ids=[i for i,name in enumerate(names) if name in source_names or name.endswith("CURRENT_RETURN_LEFT")];other_ids=[i for i in range(1,len(names)) if i not in source_ids];source_logit=Z[:,source_ids]@beta[source_ids];other_logit=beta[0]+Z[:,other_ids]@beta[other_ids]
