 audit={"schema":"GDT381_TARGET_DEFINITION_OVERLAP_AUDIT_V1","status":"PRIMARY_NUMERICAL_PASS_NONPROMOTING_SOURCE_DEFINITION_OVERLAP","chronology":"POST_PRIMARY_SCORE_BEFORE_ANY_FORMAL_REALIZATION_INSPECTION","events":len(raw),"members":int(membership.sum()),"features_total":len(names),"conservative_source_side_features":len(source_ids),"source_side_auc_for_frozen_membership":target.auc(membership,source_logit),"post_or_mixed_auc_for_frozen_membership":target.auc(membership,other_logit),"source_side_full_logit_correlation":float(np.corrcoef(source_logit,full_logit)[0,1]),"post_or_mixed_full_logit_correlation":float(np.corrcoef(other_logit,full_logit)[0,1]),"source_side_logit_variance":float(np.var(source_logit)),"full_logit_variance":float(np.var(full_logit)),"post_or_mixed_logit_variance":float(np.var(other_logit)),"primary_frozen_metrics_changed":False,"primary_promotion_honored_as_semantic_or_independent_transfer":False,"formal_realizations_inspected":False,"required_future_correction":"DEFINE_OUTCOME_FROM_POST_PIVOT_OR_PRE_RESIDUALIZED_TOPOLOGY_BEFORE_SCORING_AND_PREDICT_FROM_DISJOINT_SOURCE_FEATURES","inputs":{str(p.relative_to(ROOT)):sha(p) for p in [ART/"gdt381_voynich_target_freeze.json",ART/"gdt381_voynich_result.json",ROOT/"gdt327_joint_tuple_interlinear.tsv"]},"implementation":{str((BASE/"src/audit_target_definition_overlap.py").relative_to(ROOT)):sha(BASE/"src/audit_target_definition_overlap.py"),str((BASE/"src/run_target.py").relative_to(ROOT)):sha(BASE/"src/run_target.py"),str((BASE/"src/run_comparator.py").relative_to(ROOT)):sha(BASE/"src/run_comparator.py")},"semantic_state":"UNASSIGNED","f84":{"opened":False,"parsed":False,"retained":False,"scored":False},"claim_ceiling":"DEFINITION_OVERLAP_DIAGNOSTIC_ONLY_NO_FUNCTION_CLASS"};audit["content_hash"]=content(audit);(ART/"gdt381_target_definition_overlap.json").write_text(json.dumps(audit,indent=2,sort_keys=True)+"\n");print(json.dumps({"status":audit["status"],"source_auc":audit["source_side_auc_for_frozen_membership"],"source_correlation":audit["source_side_full_logit_correlation"]}))
